package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.joda.convert.FromString;
import org.joda.time.DurationFieldType;
import org.joda.time.PeriodType;
import org.joda.time.base.BasePeriod;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.ISOPeriodFormat;
import org.joda.time.format.PeriodFormatter;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Period_normalizedStandard_TriageGen0Test {

    @Test
    public void testNormalizedStandard_AllFieldsSupported() {
        // Test with all fields (Years, Months, Weeks, Days, Hours, Minutes, Seconds, Millis)
        Period period = new Period(1, 2, 3, 4, 5, 6, 7, 8);
        PeriodType type = PeriodType.full();
        Period result = period.normalizedStandard(type);

        assertEquals(1, result.getYears());
        assertEquals(2, result.getMonths());
        assertEquals(3, result.getWeeks());
        assertEquals(4, result.getDays());
        assertEquals(5, result.getHours());
        assertEquals(6, result.getMinutes());
        assertEquals(7, result.getSeconds());
        assertEquals(8, result.getMillis());
        assertEquals(type, result.getPeriodType());
    }

    @Test
    public void testNormalizedStandard_NoYearsOrMonths() {
        // Test where years and months are zero (skips the normalization logic)
        Period period = new Period(0, 0, 1, 2, 3, 4, 5, 6);
        PeriodType type = PeriodType.dayAndTime();
        Period result = period.normalizedStandard(type);

        assertEquals(0, result.getYears());
        assertEquals(0, result.getMonths());
        assertEquals(1, result.getWeeks());
        assertEquals(2, result.getDays());
        assertEquals(3, result.getHours());
        assertEquals(4, result.getMinutes());
        assertEquals(5, result.getSeconds());
        assertEquals(6, result.getMillis());
    }

    @Test
    public void testNormalizedStandard_NormalizeYearsAndMonths() {
        // Test normalization of years and months into the provided type
        // 13 months should become 1 year and 1 month
        Period period = new Period(0, 13, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.yearMonth();
        Period result = period.normalizedStandard(type);

        assertEquals(1, result.getYears());
        assertEquals(1, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_NormalizeOnlyMonths() {
        // Test where years are 0 but months are present, and type supports months but not years
        Period period = new Period(0, 13, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.monthAndTime();
        Period result = period.normalizedStandard(type);

        assertEquals(0, result.getYears());
        assertEquals(13, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_NormalizeOnlyYears() {
        // Test where months are 0 but years are present, and type supports years but not months
        Period period = new Period(1, 0, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.year();
        Period result = period.normalizedStandard(type);

        assertEquals(1, result.getYears());
        assertEquals(0, result.getMonths());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testNormalizedStandard_ThrowsExceptionWhenTypeMissingYearOrMonthButHasAmount() {
        // Test the case where years/months exist but the type doesn't support enough fields to normalize them
        // e.g., period has 1 year, but type only supports days/hours/etc.
        Period period = new Period(1, 0, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.dayAndTime();
        period.normalizedStandard(type);
    }

    @Test
    public void testNormalizedStandard_NegativeValues() {
        // Test with negative values to ensure math holds
        Period period = new Period(-1, -2, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.yearMonth();
        Period result = period.normalizedStandard(type);

        assertEquals(-1, result.getYears());
        assertEquals(-2, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_LargeValues() {
        // Test with large values to ensure long calculation for millis works
        Period period = new Period(0, 0, 0, 1000, 0, 0, 0, 0); // 1000 days
        PeriodType type = PeriodType.dayAndTime();
        Period result = period.normalizedStandard(type);

        assertEquals(1000, result.getDays());
    }
}
